parameters.jsCode:
let text = $input.item.json.text || '{}';
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { analysis_type: 'seasonal', resumen: 'Error al parsear salida del agente IA', error: e.message, raw: text };
}
if (!parsed.analysis_type) parsed.analysis_type = 'seasonal';
return [{ json: parsed }];

// All values come from the client's editorial_config; no client-specific fallbacks.
const ctx = $('Cargar contexto Infidash').first().json;
const cfg = ctx.settings?.editorial_config ?? {};
const list = (value) => Array.isArray(value)
  ? value.map((item) => String(item).trim()).filter(Boolean)
  : typeof value === 'string'
    ? value.split(',').map((item) => item.trim()).filter(Boolean)
    : [];
const text = (value) => (value === undefined || value === null ? '' : String(value).trim());
const topic = text(cfg.topic);
if (!topic) throw new Error('Falta editorial_config.topic para este cliente');
const siteUrl = text(cfg.siteUrl) || text(cfg.site_url);
if (!siteUrl) throw new Error('Falta editorial_config.siteUrl para este cliente');
const keywordsList = list(cfg.keywords);
const competitors = list(cfg.competitors);
return [{ json: {
  topic,
  country: text(cfg.country) || 'ES',
  keywords: keywordsList.length ? keywordsList.join(', ') : topic,
  keywords_list: keywordsList.length ? keywordsList : [topic],
  weeks_horizon: Number(cfg.weeksHorizon ?? 4),
  site_url: siteUrl,
  competitors,
  serprobotProjectId: text(cfg.serprobotProjectId) || null,
  ga4PropertyId: text(cfg.ga4PropertyId) || null,
  client_context: ctx,
} }];

const d = $input.item.json;
const rising = (d.related_queries?.rising || []).slice(0, 10);
const top    = (d.related_queries?.top    || []).slice(0, 10);
return [{ json: {
  analysis_type: 'trends',
  rising_queries: rising.map(r => ({ query: r.query, value: r.value })),
  top_queries:    top.map(t    => ({ query: t.query, value: t.value })),
  summary: `${rising.length} tendencias en alza · ${top.length} queries top detectadas`
}}];

var allItems = $input.all();
var pages = [];

for (var i = 0; i < allItems.length; i++) {
  var r = allItems[i].json;

  var path = r.landingPage || r.pagePath || r.pageLocation || '';

  if (path.indexOf('http') === 0) {
    try { path = new URL(path).pathname; } catch(e) {}
  }

  if (!path) continue;

  var views    = parseInt(r.totalUsers || r.screenPageViews || 0);
  var duration = parseFloat(r.averageSessionDuration || r.userEngagementDuration || 0);
  var events   = parseFloat(r.eventsPerSession || 0);
  var title    = r.pageTitle || path;

  pages.push({
    path:         path,
    title:        title,
    views:        views,
    duration:     duration.toFixed(0) + 's',
    duration_raw: duration,
    events_per_session: events.toFixed(2)
  });
}

pages.sort(function(a, b) { return b.views - a.views; });

var total_views = 0;
for (var j = 0; j < pages.length; j++) {
  total_views += pages[j].views;
}

var avg_duration = 0;
for (var k = 0; k < pages.length; k++) {
  avg_duration += pages[k].duration_raw;
}
avg_duration = pages.length > 0
  ? (avg_duration / pages.length).toFixed(0) + 's'
  : 'N/A';

var top10 = pages.slice(0, 10);

var high_duration = pages.slice().sort(function(a, b) {
  return b.duration_raw - a.duration_raw;
}).slice(0, 5);

var high_engagement = pages.slice().sort(function(a, b) {
  return parseFloat(b.events_per_session) - parseFloat(a.events_per_session);
}).slice(0, 5);

var parts = [];
parts.push(pages.length + ' landings analizadas. Total usuarios: ' + total_views + '.');
if (top10[0]) {
  parts.push('Top landing: ' + (top10[0].title || top10[0].path) + ' con ' + top10[0].views + ' usuarios.');
}
parts.push('Duracion media de sesion: ' + avg_duration + '.');
if (high_duration.length > 0) {
  parts.push('Mayor tiempo en pagina: ' + high_duration.slice(0, 3).map(function(p) {
    return p.path + ' (' + p.duration + ')';
  }).join(', ') + '.');
}

return [{
  json: {
    analysis_type: 'historical',
    meta: {
      total_pages_analyzed: pages.length,
      total_users: total_views,
      avg_session_duration: avg_duration,
      period_days: 30
    },
    top_performing:       top10,
    all_pages:            pages,
    high_duration_pages:  high_duration,
    high_engagement_pages: high_engagement,
    best_content: top10[0] ? (top10[0].title || top10[0].path) : 'N/A',
    insights: parts.join(' ')
  }
}];

const tl = $input.item.json?.interest_over_time?.timeline_data || [];
const monthly = {};
tl.forEach(p => {
  const dt = new Date(p.timestamp * 1000);
  const k  = `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}`;
  if (!monthly[k]) monthly[k] = [];
  monthly[k].push(parseInt(p.values?.[0]?.extracted_value || 0));
});
const avgs = Object.entries(monthly)
  .map(([m, v]) => ({ month: m, avg: Math.round(v.reduce((a,b)=>a+b,0)/v.length) }))
  .sort((a, b) => b.avg - a.avg);
return [{ json: {
  analysis_type:    'seasonal',
  monthly_interest: avgs,
  peak_month:       avgs[0]?.month || 'N/A',
  top_months:       avgs.slice(0, 4),
  seasonal_tip:     `Pico de interés detectado en ${avgs[0]?.month}`
}}];

var allItems = $input.all();
var queries = [];

for (var i = 0; i < allItems.length; i++) {
  var r = allItems[i].json;

  var query       = r.query || '';
  var clicks      = parseInt(r.clicks || 0);
  var impressions = parseInt(r.impressions || 0);
  var ctr         = parseFloat(r.ctr || 0);
  var position    = parseFloat(r.position || 0);

  if (!query || query === '(not set)') continue;

  queries.push({
    query:       query,
    clicks:      clicks,
    impressions: impressions,
    ctr:         (ctr * 100).toFixed(2) + '%',
    ctr_raw:     ctr,
    position:    position.toFixed(1)
  });
}

// Ordenar por clicks desc
queries.sort(function(a, b) { return b.clicks - a.clicks; });

// Totales
var total_clicks = 0;
var total_impressions = 0;
for (var j = 0; j < queries.length; j++) {
  total_clicks      += queries[j].clicks;
  total_impressions += queries[j].impressions;
}

var avg_ctr = total_impressions > 0
  ? ((total_clicks / total_impressions) * 100).toFixed(2) + '%'
  : 'N/A';

var avg_position = 0;
for (var k = 0; k < queries.length; k++) {
  avg_position += parseFloat(queries[k].position);
}
avg_position = queries.length > 0
  ? (avg_position / queries.length).toFixed(1)
  : 'N/A';

// Top 10 por clicks
var top10 = queries.slice(0, 10);

// Oportunidades: posicion 4-15 + impresiones altas + CTR bajo
var opportunities = [];
for (var l = 0; l < queries.length; l++) {
  var q = queries[l];
  if (parseFloat(q.position) >= 4 &&
      parseFloat(q.position) <= 15 &&
      q.impressions > 50 &&
      q.ctr_raw < 0.05) {
    opportunities.push(q);
  }
}
opportunities.sort(function(a, b) { return b.impressions - a.impressions; });
opportunities = opportunities.slice(0, 10);

// Top por impresiones (volumen sin clicks)
var top_impressions = queries.slice().sort(function(a, b) {
  return b.impressions - a.impressions;
}).slice(0, 10);

// Ya en top 3
var top3 = queries.filter(function(q) {
  return parseFloat(q.position) <= 3;
}).slice(0, 10);

var parts = [];
parts.push(queries.length + ' queries analizadas.');
parts.push('Total clicks: ' + total_clicks + '. Total impresiones: ' + total_impressions + '.');
parts.push('CTR medio: ' + avg_ctr + '. Posicion media: ' + avg_position + '.');
if (top10[0]) {
  parts.push('Top query: "' + top10[0].query + '" con ' + top10[0].clicks + ' clicks (pos ' + top10[0].position + ').');
}
if (opportunities.length > 0) {
  parts.push(opportunities.length + ' oportunidades (pos 4-15, CTR bajo): ' +
    opportunities.slice(0, 3).map(function(q) {
      return '"' + q.query + '" (pos ' + q.position + ', ' + q.impressions + ' imp)';
    }).join(', ') + '.');
}

return [{
  json: {
        analysis_type: 'queries_analytics',
    meta: {
      total_queries:     queries.length,
      total_clicks:      total_clicks,
      total_impressions: total_impressions,
      avg_ctr:           avg_ctr,
      avg_position:      avg_position,
      period_days:       30
    },
    top_by_clicks:      top10,
    top_by_impressions: top_impressions,
    top3_positions:     top3,
    opportunities:      opportunities,
    all_queries:        queries,
    insights: parts.join(' ')
  }
}];

var allItems = $input.all();
var DEBUG_keys = allItems.length > 0 ? Object.keys(allItems[0].json) : [];
var pages = [];

for (var i = 0; i < allItems.length; i++) {
  var r = allItems[i].json;

  // Search Console pages puede llamar al campo de distintas formas
  var page = r.page || r.keys || r.url || r.pagePath || '';

  // Si viene como array (a veces GSC devuelve keys:[page])
  if (Array.isArray(page)) page = page[0] || '';

  // Limpiar dominio si viene URL completa — dejar solo el path
  if (page.indexOf('http') === 0) {
    try { page = new URL(page).pathname; } catch(e) {}
  }

  if (!page || page === '(not set)') continue;

  var clicks      = parseInt(r.clicks || 0);
  var impressions = parseInt(r.impressions || 0);
  var ctr         = parseFloat(r.ctr || 0);
  var position    = parseFloat(r.position || 0);

  pages.push({
    page:        page,
    clicks:      clicks,
    impressions: impressions,
    ctr:         (ctr * 100).toFixed(2) + '%',
    ctr_raw:     ctr,
    position:    position.toFixed(1),
    position_raw: position
  });
}

// Ordenar por clicks desc
pages.sort(function(a, b) { return b.clicks - a.clicks; });

// Totales
var total_clicks = 0;
var total_impressions = 0;
for (var j = 0; j < pages.length; j++) {
  total_clicks      += pages[j].clicks;
  total_impressions += pages[j].impressions;
}

var avg_ctr = total_impressions > 0
  ? ((total_clicks / total_impressions) * 100).toFixed(2) + '%'
  : 'N/A';

var avg_position = 0;
for (var k = 0; k < pages.length; k++) {
  avg_position += pages[k].position_raw;
}
avg_position = pages.length > 0
  ? (avg_position / pages.length).toFixed(1)
  : 'N/A';

// Top 10 por clicks
var top10 = pages.slice(0, 10);

// Oportunidades: posicion 4-15 + impresiones altas + CTR bajo
// Son las paginas que Google ya muestra pero nadie clickea
var opportunities = [];
for (var l = 0; l < pages.length; l++) {
  var p = pages[l];
  if (p.position_raw >= 4 &&
      p.position_raw <= 15 &&
      p.impressions > 30 &&
      p.ctr_raw < 0.05) {
    opportunities.push(p);
  }
}
opportunities.sort(function(a, b) { return b.impressions - a.impressions; });
opportunities = opportunities.slice(0, 10);

// Top por impresiones (se ven mucho pero no se clickean)
var top_impressions = pages.slice().sort(function(a, b) {
  return b.impressions - a.impressions;
}).slice(0, 10);

// Ya en top 3 (proteger — buen contenido)
var top3 = pages.filter(function(p) {
  return p.position_raw <= 3;
}).slice(0, 10);

// Paginas en pag 2 (pos 11-20) con potencial
var page2 = pages.filter(function(p) {
  return p.position_raw >= 11 && p.position_raw <= 20;
}).slice(0, 10);

var parts = [];
parts.push(pages.length + ' paginas analizadas en Search Console.');
parts.push('Total clicks: ' + total_clicks + '. Total impresiones: ' + total_impressions + '.');
parts.push('CTR medio: ' + avg_ctr + '. Posicion media: ' + avg_position + '.');
if (top10[0]) {
  parts.push('Pagina top: "' + top10[0].page + '" con ' + top10[0].clicks + ' clicks (pos ' + top10[0].position + ').');
}
if (opportunities.length > 0) {
  parts.push(opportunities.length + ' paginas con oportunidad de mejora (pos 4-15, CTR bajo): ' +
    opportunities.slice(0, 3).map(function(p) {
      return '"' + p.page + '" (pos ' + p.position + ', ' + p.impressions + ' imp)';
    }).join(', ') + '.');
}
if (top3.length > 0) {
  parts.push('Paginas en top 3 (proteger): ' +
    top3.slice(0, 3).map(function(p) { return '"' + p.page + '"'; }).join(', ') + '.');
}

return [{
  json: {
    analysis_type: 'search_console',

    meta: {
      total_pages:       pages.length,
      total_clicks:      total_clicks,
      total_impressions: total_impressions,
      avg_ctr:           avg_ctr,
      avg_position:      avg_position,
      period_days:       30
    },
    top_by_clicks:      top10,
    top_by_impressions: top_impressions,
    top3_positions:     top3,
    page2_opportunities: page2,
    opportunities:      opportunities,
    all_pages:          pages,
    insights:           parts.join(' ')
  }
}];

parameters.text:
=Actúa como un experto analista de contenido y competencia SEO. Tu tarea es analizar exahustivamente el contenido extraído de la página web de un competidor.



Contenido para analizar:

{{ $json.data }}
"""
Basado en el texto anterior, genera un JSON estricto (sin markdown, sin bloques de código) con la siguiente estructura:
{
  "headers": ["titulo pricipal del post"],
