const items = $input.all();

const articulos = items.map((item, index) => {
  let header = '';
  let resumen = '';

  try {
    const parsed = JSON.parse(item.json.text);

    header = parsed.headers?.[0] || '';
    resumen = Array.isArray(parsed.resumen) 
      ? parsed.resumen.join(' ') 
      : parsed.resumen || '';

  } catch (e) {
    header = `Error item ${index + 1}: ${e.message}`;
    resumen = '';
  }

  return {
    id: index + 1,
    header,
    resumen
  };
});

return [{
  json: {
    articulos,
    total: articulos.length
  }
}];

// ─── Parsear correctamente: data llega como STRING ────────────────────────
const raw = $input.item.json;
let parsed;

try {
  // El JSON de SerpLab viene como string en raw.data → hay que parsearlo
  parsed = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw.data;
} catch(e) {
  return [{ json: { error: 'JSON inválido en raw.data', detail: e.message, sample: String(raw.data).substring(0, 300) } }];
}

const rows      = parsed?.report_data || [];
const meta_root = parsed || {};

// ─── Helpers ──────────────────────────────────────────────────────────────
const g = (obj, ...keys) => {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return null;
};

const num = v => {
  if (v === null || v === undefined || v === '-' || v === '' || v === 'N/A') return null;
  const n = parseFloat(String(v).replace(',', '.'));
  return isNaN(n) ? null : n;
};

// ─── Normalizar keywords ──────────────────────────────────────────────────
const keywords = rows.map(r => {
  const pos_latest = num(g(r, 'latest_position',   'posición_más_última'));
  const pos_best   = num(g(r, 'best_ever_position', 'mejor_posición_de_todos'));
  const vol_local  = num(g(r, 'volume_local',       'volumen_local'));
  const cpc_local  = num(g(r, 'cpc_local')) ?? 0;
  const url        = g(r, 'found_serp', 'serp_encontrado') || null;

  return {
    id:          g(r, 'keyword_id', 'id_palabra_clave'),
    keyword:     g(r, 'keyword', 'palabra_clave') || '',
    change:      num(g(r, 'change', 'cambio')) ?? 0,
    pos_latest,
    pos_best,
    pos_first:   num(g(r, 'first_ever_position', 'primera_posición_de_todos')),
    url:         url === 'NOT FOUND' || url === '' ? null : url,
    not_found:   url === 'NOT FOUND',
    vol_local,
    vol_global:  num(g(r, 'volume_global', 'volumen_global')),
    cpc_local,
    cpc_global:  num(g(r, 'cpc_global')) ?? 0,
    cmp_local:   num(g(r, 'cmp_local'))  ?? 0,
    updated:     g(r, 'updated', 'actualizado'),
    gap_to_best: (pos_latest !== null && pos_best !== null) ? pos_latest - pos_best : null,
  };
}).filter(k => k.keyword.length > 0);

// ─── Clasificar ───────────────────────────────────────────────────────────
const ranking    = keywords.filter(k => k.pos_latest !== null && !k.not_found);
const no_rank    = keywords.filter(k => k.pos_latest === null || k.not_found);

const pos1_3     = ranking.filter(k => k.pos_latest <= 3);
const pos4_10    = ranking.filter(k => k.pos_latest >= 4  && k.pos_latest <= 10);
const pos11_20   = ranking.filter(k => k.pos_latest >= 11 && k.pos_latest <= 20);

const lost_ground = ranking
  .filter(k => k.gap_to_best !== null && k.gap_to_best > 3)
  .sort((a, b) => b.gap_to_best - a.gap_to_best);

const recoverable = ranking
  .filter(k => k.pos_latest >= 11 && k.pos_best !== null && k.pos_best <= 10);

const high_cpc = keywords
  .filter(k => k.cpc_local > 1 && (k.pos_latest === null || k.pos_latest > 3))
  .sort((a, b) => b.cpc_local - a.cpc_local);

const improved = ranking
  .filter(k => k.change < 0)
  .sort((a, b) => a.change - b.change);

const at_best = ranking.filter(k => k.gap_to_best === 0);

// ─── Agrupar por URL ──────────────────────────────────────────────────────
const by_url = {};
keywords.forEach(k => {
  const u = k.url || '/';
  if (!by_url[u]) by_url[u] = [];
  by_url[u].push({ keyword: k.keyword, pos: k.pos_latest, best: k.pos_best });
});
const pages = Object.entries(by_url)
  .map(([url, kws]) => ({
    url,
    keywords_count: kws.length,
    keywords: kws.sort((a, b) => (a.pos ?? 999) - (b.pos ?? 999))
  }))
  .sort((a, b) => b.keywords_count - a.keywords_count);

const fmt = k => ({
  keyword: k.keyword, pos: k.pos_latest, best_ever: k.pos_best,
  gap: k.gap_to_best, vol_local: k.vol_local, cpc: k.cpc_local,
  url: k.url, change: k.change
});

// ─── Output ───────────────────────────────────────────────────────────────
return [{
  json: {
    analysis_type: 'serplab_rankings',
    meta: {
      period:             `${meta_root.start || ''} → ${meta_root.end || ''}`,
      report_id:          meta_root.id || null,
      total_keywords:     keywords.length,
      ranking:            ranking.length,
      not_ranking:        no_rank.length,
      at_best_ever:       at_best.length,
      improved_this_week: improved.length,
    },
    top3:           pos1_3.map(fmt),
    page1_pos4_10:  pos4_10.map(fmt),
    page2_pos11_20: pos11_20.map(fmt),
    not_ranking:    no_rank.map(k => ({ keyword: k.keyword, vol: k.vol_local, not_found: k.not_found })),
    at_best_ever:   at_best.map(fmt),
    improved_this_week: improved.map(fmt),
    opportunities: {
      lost_ground:      lost_ground.map(fmt),
      recoverable:      recoverable.map(fmt),
      high_cpc_not_top3: high_cpc.map(fmt),
    },
    pages_analysis: pages,
    insights: [
      `${keywords.length} keywords rastreadas. ${ranking.length} rankean, ${no_rank.length} sin posición.`,
      pos1_3.length     ? `TOP 3: ${pos1_3.map(k => `"${k.keyword}" (pos ${k.pos_latest})`).join(', ')}.` : 'Ninguna en top 3.',
      pos4_10.length    ? `Pág1 pos4-10: ${pos4_10.map(k => `"${k.keyword}"`).join(', ')}.` : '',
      lost_ground.length? `${lost_ground.length} keywords perdieron posición: ${lost_ground.slice(0,3).map(k=>`"${k.keyword}" (ahora ${k.pos_latest}, mejor ${k.pos_best})`).join(', ')}.` : '',
      recoverable.length? `${recoverable.length} recuperables (top10 → pág2): ${recoverable.map(k=>`"${k.keyword}"`).join(', ')}.` : '',
      high_cpc.length   ? `CPC alto sin top3: ${high_cpc.slice(0,3).map(k=>`"${k.keyword}" €${k.cpc_local}`).join(', ')}.` : '',
      pages.length      ? `URL con más keywords: ${pages[0].url} (${pages[0].keywords_count}).` : '',
    ].filter(Boolean).join(' ')
  }
}];

const items = $input.all();
const find = type => items.find(i => i.json.analysis_type === type)?.json || {};

// ── Helpers de formateo ──────────────────────────────────────────────────
const NA = '(sin datos)';
const list = (arr, mapper) => {
  if (!Array.isArray(arr) || arr.length === 0) return '  ' + NA;
  return arr.map(x => '  - ' + (mapper ? mapper(x) : x)).join('\n');
};
// Si el parser detectó un error de JSON, devolvemos el fallback en vez de romper el prompt
const errBlock = b => b && b.unavailable
  ? `⚠️ Fuente no disponible (${b.error}). ${b.insights || NA}`
  : b && b.error
  ? `⚠️ No se pudo parsear el análisis de este bloque (${b.error}).\nResumen crudo: ${b.insights || b.raw || NA}`
  : null;

// ── TENDENCIAS ────────────────────────────────────────────────────────────
const trends = find('trends');
const trends_data = errBlock(trends) || [
  `Resumen: ${trends.resumen || NA}`,
  `Tendencias relevantes:`,
  list(trends.tendencias_relevantes, t => `${t.query} (urgencia ${t.urgencia}): ${t.motivo}`),
  `Ángulos de contenido sugeridos:`,
  list(trends.angulos_de_contenido)
].join('\n');

// ── HISTÓRICO GA4 ─────────────────────────────────────────────────────────
const hist = find('historical');
const historical_data = errBlock(hist) || [
  `Resumen: ${hist.resumen || NA}`,
  `Patrones ganadores:`,
  list(hist.patrones_ganadores),
  `Contenido a actualizar:`,
  list(hist.contenido_a_actualizar),
  `Contenido a replicar en el nuevo calendario:`,
  list(hist.contenido_a_replicar)
].join('\n');

// ── ESTACIONALIDAD ────────────────────────────────────────────────────────
const seasonal = find('seasonal');
const seasonal_data = errBlock(seasonal) || [
  `Resumen: ${seasonal.resumen || NA}`,
  `Alerta estacional: ${seasonal.alerta_estacional || 'sin alertas próximas'}`,
  `Temas a anticipar:`,
  list(seasonal.temas_a_anticipar),
  `Recomendación de timing: ${seasonal.recomendacion_timing || NA}`
].join('\n');

// ── RANKINGS SERPLAB ──────────────────────────────────────────────────────
const serplab = find('serplab_rankings');
const serplab_data = errBlock(serplab) || [
  `Resumen: ${serplab.resumen || NA}`,
  `Keywords a rescatar (perdieron posición):`,
  list(serplab.keywords_a_rescatar, k => `${k.keyword} (actual ${k.posicion_actual}, mejor ${k.mejor_posicion}): ${k.accion}`),
  `Keywords cerca de página 1:`,
  list(serplab.keywords_cerca_de_pagina_1, k => `${k.keyword} (pos ${k.posicion_actual}): ${k.accion}`),
  `Oportunidades de alto valor sin explotar:`,
  list(serplab.oportunidades_alto_valor_sin_explotar, k => `${k.keyword} (CPC €${k.cpc}): ${k.accion}`)
].join('\n');

// ── SEARCH CONSOLE — PÁGINAS ──────────────────────────────────────────────
const sc = find('search_console');
const search_console_data = errBlock(sc) || [
  `Resumen: ${sc.resumen || NA}`,
  `Páginas a proteger (van bien, no tocar):`,
  list(sc.paginas_proteger),
  `Páginas a optimizar para mejorar CTR:`,
  list(sc.paginas_optimizar_ctr, p => `${p.pagina} (pos ${p.posicion}): ${p.accion_sugerida}`),
  `Páginas a reforzar con contenido nuevo (pillar/cluster):`,
  list(sc.paginas_reforzar_con_contenido_nuevo, p => `${p.pagina}: ${p.tema_sugerido_para_pillar_o_cluster}`)
].join('\n');

// ── SEARCH CONSOLE — QUERIES ──────────────────────────────────────────────
const queries = find('queries_analytics');
const queries_data = errBlock(queries) || [
  `Resumen: ${queries.resumen || NA}`,
  `Clusters de intención de búsqueda:`,
  list(queries.clusters_de_intencion, c => `${c.tema} [prioridad ${c.prioridad}] (${(c.queries || []).join(', ')}): ${c.justificacion}`),
  `Keywords con impresiones altas y pocos clicks (oportunidad):`,
  list(queries.keywords_alta_impresion_bajo_click)
].join('\n');

// ── COMPETIDORES Y PUBLICADOS (sin agente intermedio, se mantienen igual) ──
const comp = items.find(i => i.json.analysis_type === 'competitors')?.json || {};
const published = find('published_articles');

// ── Datos DIRECTOS del nodo ⚙️ Configuración (incluye keywords) ────────────
const cfg = $('⚙️ Configuración').first().json;
const keywordsRaw  = cfg.keywords || '';
const keywordsList = String(keywordsRaw).split(',').map(k => k.trim()).filter(Boolean);

// Datos editoriales canónicos desde Infidash
const calendario = $('Cargar contexto Infidash').first().json.planItems || [];

return [{ json: {
  trends_data,
  historical_data,
  seasonal_data,
  serplab_data,
  search_console_data,
  queries_data,
  competitor_data:           JSON.stringify(comp,       null, 2),
  published_data:            JSON.stringify(published,  null, 2),
  calendario_editorial_data: JSON.stringify(calendario, null, 2),
  config: {
    topic:         cfg.topic,
    weeks:         cfg.weeks_horizon,
    country:       cfg.country,
    keywords:      keywordsRaw,
    keywords_list: keywordsList
  }
}}];

